import cyclopts

app = cyclopts.App()

@app.default
def status():
    """Show the current status."""
    print("Status: OK")

@app.command
def start():
    """Start the service."""
    print("Starting...")

@app.command
def stop():
    """Stop the service."""
    print("Stopping...")

if __name__ == "__main__":
    app()
